FROM sales |> WHERE NOT (region = 'west' AND t >= TIMESTAMP '2024-03-01' AND t < TIMESTAMP '2024-05-01') |> AGGREGATE sum(units) AS sum_units GROUP BY date_trunc('month', t) AS x_expr, region |> CALL impute(x_expr, [region], sum_units, value => 0, flag => imputed) |> AGGREGATE bar(x => scaled(x_expr, title => 'date_trunc(''month'', t)'), y => scaled(sum_units, title => 'sum(units)'), color => region, orient => 'vertical') AS chart
